SET LOCAL ROLE sim_guru_owner;
CREATE TABLE app.teaching_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),academic_period_id uuid NOT NULL REFERENCES app.academic_periods(id),user_id uuid NOT NULL REFERENCES app.app_users(id),subject_id uuid NOT NULL REFERENCES app.subjects(id),class_id uuid NOT NULL REFERENCES app.classes(id),day_index smallint NOT NULL CHECK(day_index BETWEEN 0 AND 6),time_start time(4) NOT NULL,time_end time(4) NOT NULL,scheduled_jtm numeric(12,4) NOT NULL CHECK(scheduled_jtm>0),rest_minutes integer NOT NULL CHECK(rest_minutes BETWEEN 0 AND 600),minutes_per_jtm integer NOT NULL CHECK(minutes_per_jtm BETWEEN 1 AND 180),valid_from date NOT NULL,valid_to date NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','closed','archived')),snapshot jsonb NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),replaces_id uuid REFERENCES app.teaching_schedules(id),archived_at timestamptz,CHECK(time_end>time_start),CHECK(isfinite(valid_from) AND isfinite(valid_to) AND valid_to-valid_from BETWEEN 0 AND 365),CHECK((state='archived')=(archived_at IS NOT NULL)));
CREATE INDEX schedules_teacher_window ON app.teaching_schedules(user_id,day_index,valid_from,valid_to) WHERE state<>'archived';
CREATE INDEX schedules_class_window ON app.teaching_schedules(class_id,day_index,valid_from,valid_to) WHERE state<>'archived';
CREATE INDEX schedules_period_day ON app.teaching_schedules(academic_period_id,day_index);
CREATE INDEX schedules_subject ON app.teaching_schedules(subject_id);
CREATE INDEX schedules_replaces ON app.teaching_schedules(replaces_id) WHERE replaces_id IS NOT NULL;
CREATE TABLE ops.schedule_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL REFERENCES app.app_users(id),request jsonb NOT NULL,state_revision bigint NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes',consumed_at timestamptz);
CREATE INDEX schedule_previews_actor ON ops.schedule_previews(actor_id);
CREATE INDEX schedule_previews_expiry ON ops.schedule_previews(expires_at);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['app.teaching_schedules','ops.schedule_previews'] LOOP EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY owner_internal ON %s TO sim_guru_owner USING(true) WITH CHECK(true)',t);END LOOP;END $$;
CREATE FUNCTION app.schedule_dependencies() RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN
 IF to_regclass('app.activity_occurrences') IS NOT NULL OR to_regclass('app.teaching_occurrences') IS NOT NULL OR to_regclass('app.exam_periods') IS NOT NULL OR to_regclass('finance.honor_periods') IS NOT NULL THEN RAISE EXCEPTION 'CONTEXT_DEPENDENCY_UNAVAILABLE' USING ERRCODE='55000';END IF;END $$;
CREATE OR REPLACE FUNCTION app.calendar_dependencies(p_date date) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ BEGIN
 PERFORM app.schedule_dependencies();RETURN jsonb_build_object('assignmentIntegration','teaching_ready','activeExamPeriods','[]'::jsonb,'activeExamPeriodIds','[]'::jsonb);END $$;
CREATE FUNCTION app.schedule_weekday_exists(p_from date,p_to date,p_day int) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT p_from+((p_day-extract(dow FROM p_from)::int+7)%7)<=p_to $$;
CREATE FUNCTION app.schedule_dto(p_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT jsonb_build_object('id',s.id,'academicPeriodId',s.academic_period_id,'userId',s.user_id,'subjectId',s.subject_id,'classId',s.class_id,'dayIndex',s.day_index,'timeStart',to_char(s.time_start,'HH24:MI'),'timeEnd',s.time_end::text,'scheduledJtm',s.scheduled_jtm::text,'restMinutes',s.rest_minutes,'minutesPerJtm',s.minutes_per_jtm,'validFrom',s.valid_from,'validTo',s.valid_to,'state',s.state,'version',s.version::text,'teacherName',s.snapshot->>'teacherName','subjectName',s.snapshot->>'subjectName','className',s.snapshot->>'className','periodLabel',s.snapshot->>'periodLabel','replacesId',s.replaces_id) FROM app.teaching_schedules s WHERE id=p_id $$;
CREATE FUNCTION app.schedule_candidate(p_data jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE p app.academic_periods%ROWTYPE;c app.classes%ROWTYPE;u app.app_users%ROWTYPE;subject app.subjects%ROWTYPE;minutes int;start_sec numeric;end_sec numeric;start_time time;finish time;jtm numeric;v_from date;v_to date;day int;rest int;allowed text[]:=ARRAY['academicPeriodId','userId','subjectId','classId','dayIndex','timeStart','scheduledJtm','restMinutes','validFrom','validTo'];BEGIN
 IF p_data IS NULL OR jsonb_typeof(p_data)<>'object' OR p_data-allowed<>'{}'::jsonb OR NOT p_data ?& allowed OR coalesce(p_data->>'timeStart','')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR coalesce(p_data->>'scheduledJtm','')!~'^(0|[1-9][0-9]{0,7})(\.[0-9]{1,4})?$' THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;
 SELECT * INTO p FROM app.academic_periods WHERE id=(p_data->>'academicPeriodId')::uuid;SELECT * INTO c FROM app.classes WHERE id=(p_data->>'classId')::uuid;SELECT * INTO u FROM app.app_users WHERE id=(p_data->>'userId')::uuid;SELECT * INTO subject FROM app.subjects WHERE id=(p_data->>'subjectId')::uuid;
 SELECT minutes_per_jtm INTO minutes FROM app.school_profiles;
 v_from:=(p_data->>'validFrom')::date;v_to:=(p_data->>'validTo')::date;day:=(p_data->>'dayIndex')::int;rest:=(p_data->>'restMinutes')::int;jtm:=(p_data->>'scheduledJtm')::numeric;start_time:=(p_data->>'timeStart')::time;start_sec:=extract(epoch FROM start_time);end_sec:=start_sec+(jtm*minutes+rest)*60;
 IF p.id IS NULL OR p.archived_at IS NOT NULL OR c.id IS NULL OR c.archived_at IS NOT NULL OR c.academic_period_id<>p.id OR u.id IS NULL OR u.status<>'active' OR subject.id IS NULL OR subject.archived_at IS NOT NULL OR minutes IS NULL OR jtm<=0 OR rest NOT BETWEEN 0 AND 600 OR day NOT BETWEEN 0 AND 6 OR v_from IS NULL OR v_to IS NULL OR NOT isfinite(v_from) OR NOT isfinite(v_to) OR v_to-v_from NOT BETWEEN 0 AND 365 OR v_from<p.date_start OR v_to>p.date_end OR NOT app.schedule_weekday_exists(v_from,v_to,day) OR end_sec>=86400 OR end_sec<=start_sec THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;
 finish:=time '00:00'+end_sec*interval '1 second';
 RETURN jsonb_build_object('academic_period_id',p.id,'user_id',u.id,'subject_id',subject.id,'class_id',c.id,'day_index',day,'time_start',start_time,'time_end',finish,'scheduled_jtm',jtm::text,'rest_minutes',rest,'minutes_per_jtm',minutes,'valid_from',v_from,'valid_to',v_to,'snapshot',jsonb_build_object('teacherName',u.full_name,'subjectName',subject.name,'className',c.name,'periodLabel',(SELECT label FROM app.academic_years WHERE id=p.academic_year_id)||' · Semester '||p.semester));END $$;
CREATE FUNCTION app.schedule_collisions(p_candidate jsonb,p_ignore uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'teacher',s.user_id=(p_candidate->>'user_id')::uuid,'class',s.class_id=(p_candidate->>'class_id')::uuid,'dayIndex',s.day_index,'timeStart',s.time_start::text,'timeEnd',s.time_end::text,'validFrom',greatest(s.valid_from,(p_candidate->>'valid_from')::date),'validTo',least(s.valid_to,(p_candidate->>'valid_to')::date)) ORDER BY s.time_start,s.id),'[]'::jsonb) FROM app.teaching_schedules s WHERE s.id IS DISTINCT FROM p_ignore AND s.state<>'archived' AND s.academic_period_id=(p_candidate->>'academic_period_id')::uuid AND s.day_index=(p_candidate->>'day_index')::int AND (s.user_id=(p_candidate->>'user_id')::uuid OR s.class_id=(p_candidate->>'class_id')::uuid) AND s.time_start<(p_candidate->>'time_end')::time AND(s.time_end>(p_candidate->>'time_start')::time) AND s.valid_from<=(p_candidate->>'valid_to')::date AND s.valid_to>=(p_candidate->>'valid_from')::date AND app.schedule_weekday_exists(greatest(s.valid_from,(p_candidate->>'valid_from')::date),least(s.valid_to,(p_candidate->>'valid_to')::date),s.day_index) $$;
CREATE FUNCTION app.schedule_save(p_session text,p_id uuid,p_version bigint,p_data jsonb,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE old app.teaching_schedules%ROWTYPE;c jsonb;new_id uuid;today date:=(clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::date;revise boolean:=false;BEGIN
 PERFORM app.master_guard(p_session,true);PERFORM app.schedule_dependencies();IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;PERFORM set_config('app.master_reason',p_reason,true);
 IF p_id IS NOT NULL THEN SELECT * INTO old FROM app.teaching_schedules WHERE id=p_id FOR UPDATE;IF old.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF old.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;IF old.state<>'active' OR old.valid_to<today THEN RAISE EXCEPTION 'SCHEDULE_HISTORICAL' USING ERRCODE='42501';END IF;END IF;
 c:=app.schedule_candidate(p_data);IF(c->>'valid_from')::date<today OR(p_id IS NOT NULL AND old.academic_period_id<>(c->>'academic_period_id')::uuid) THEN RAISE EXCEPTION 'SCHEDULE_HISTORICAL' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(app.schedule_collisions(c,p_id))>0 THEN RAISE EXCEPTION 'SCHEDULE_COLLISION' USING ERRCODE='23505';END IF;
 revise:=p_id IS NOT NULL AND old.valid_from<today;
 IF revise THEN IF(c->>'valid_from')::date>old.valid_to THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;UPDATE app.teaching_schedules SET valid_to=(c->>'valid_from')::date-1,state='closed',version=version+1 WHERE id=p_id;END IF;
 IF p_id IS NULL OR revise THEN
 INSERT INTO app.teaching_schedules(academic_period_id,user_id,subject_id,class_id,day_index,time_start,time_end,scheduled_jtm,rest_minutes,minutes_per_jtm,valid_from,valid_to,snapshot,replaces_id)
 SELECT r.academic_period_id,r.user_id,r.subject_id,r.class_id,r.day_index,r.time_start,r.time_end,r.scheduled_jtm,r.rest_minutes,r.minutes_per_jtm,r.valid_from,r.valid_to,r.snapshot,CASE WHEN revise THEN p_id ELSE null END FROM jsonb_populate_record(null::app.teaching_schedules,c) r RETURNING id INTO new_id;
 ELSE UPDATE app.teaching_schedules s SET(user_id,subject_id,class_id,day_index,time_start,time_end,scheduled_jtm,rest_minutes,minutes_per_jtm,valid_from,valid_to,snapshot)=(SELECT r.user_id,r.subject_id,r.class_id,r.day_index,r.time_start,r.time_end,r.scheduled_jtm,r.rest_minutes,r.minutes_per_jtm,r.valid_from,r.valid_to,r.snapshot FROM jsonb_populate_record(null::app.teaching_schedules,c) r),version=s.version+1 WHERE id=p_id RETURNING id INTO new_id;END IF;
 RETURN jsonb_build_object('schedule',app.schedule_dto(new_id),'revised',revise,'previousId',CASE WHEN revise THEN p_id ELSE null END);END $$;
CREATE FUNCTION app.schedule_stop_internal(p_id uuid,p_version bigint,p_from date,p_apply boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE old app.teaching_schedules%ROWTYPE;today date:=(clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::date;mode text;BEGIN
 SELECT * INTO old FROM app.teaching_schedules WHERE id=p_id FOR UPDATE;IF old.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0002';END IF;IF old.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001';END IF;
 IF old.state<>'active' OR old.valid_to<today OR p_from IS NULL OR NOT isfinite(p_from) OR p_from<today OR p_from>old.valid_to THEN RAISE EXCEPTION 'SCHEDULE_HISTORICAL' USING ERRCODE='42501';END IF;
 mode:=CASE WHEN p_from<=old.valid_from THEN 'archive' ELSE 'close' END;
 IF p_apply THEN IF mode='archive' THEN UPDATE app.teaching_schedules SET state='archived',archived_at=clock_timestamp(),version=version+1 WHERE id=p_id;ELSE UPDATE app.teaching_schedules SET state='closed',valid_to=p_from-1,version=version+1 WHERE id=p_id;END IF;END IF;
 RETURN jsonb_build_object('id',old.id,'teacherName',old.snapshot->>'teacherName','className',old.snapshot->>'className','validFrom',old.valid_from,'validTo',old.valid_to,'stopFrom',p_from,'operation',mode,'version',old.version::text);END $$;
CREATE FUNCTION app.schedule_stop(p_session text,p_id uuid,p_version bigint,p_from date,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result jsonb;BEGIN
 PERFORM app.master_guard(p_session,true);PERFORM app.schedule_dependencies();IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;PERFORM set_config('app.master_reason',p_reason,true);result:=app.schedule_stop_internal(p_id,p_version,p_from,true);RETURN result;END $$;
CREATE FUNCTION app.schedule_filtered(p_filter jsonb,p_actor uuid DEFAULT null) RETURNS SETOF app.teaching_schedules LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT s.* FROM app.teaching_schedules s WHERE(p_actor IS NULL OR s.user_id=p_actor) AND(coalesce(p_filter->>'q','')='' OR position(lower(p_filter->>'q') in lower(concat_ws(' ',s.snapshot->>'teacherName',s.snapshot->>'subjectName',s.snapshot->>'className',s.snapshot->>'periodLabel')))>0) AND(coalesce(p_filter->>'academicYearId','')='' OR EXISTS(SELECT 1 FROM app.academic_periods ap WHERE ap.id=s.academic_period_id AND ap.academic_year_id::text=p_filter->>'academicYearId')) AND(coalesce(p_filter->>'academicPeriodId','')='' OR s.academic_period_id::text=p_filter->>'academicPeriodId') AND(coalesce(p_filter->>'userId','')='' OR s.user_id::text=p_filter->>'userId') AND(coalesce(p_filter->>'subjectId','')='' OR s.subject_id::text=p_filter->>'subjectId') AND(coalesce(p_filter->>'classId','')='' OR s.class_id::text=p_filter->>'classId') AND(coalesce(p_filter->>'dayIndex','')='' OR s.day_index::text=p_filter->>'dayIndex') AND(coalesce(p_filter->>'state','')='' OR s.state=p_filter->>'state') AND(coalesce(p_filter->>'validFrom','')='' OR s.valid_to>=nullif(p_filter->>'validFrom','')::date) AND(coalesce(p_filter->>'validTo','')='' OR s.valid_from<=nullif(p_filter->>'validTo','')::date) $$;
CREATE FUNCTION app.schedule_list(p_session text,p_filter jsonb,p_mine boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;page int:=(p_filter->>'page')::int;size int:=(p_filter->>'pageSize')::int;result jsonb;BEGIN
 actor:=auth_private.lifecycle_self(p_session);IF auth_private.resolve_actor(true) IS NULL THEN RAISE EXCEPTION 'ONBOARDING_REQUIRED' USING ERRCODE='42501';END IF;IF NOT p_mine THEN PERFORM auth_private.require_admin();END IF;
 IF page IS NULL OR size IS NULL OR page NOT BETWEEN 1 AND 100000 OR size NOT BETWEEN 1 AND 100 OR p_mine IS NULL OR coalesce(p_filter->>'state','') NOT IN('','active','closed','archived') OR length(coalesce(p_filter->>'q',''))>100 THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;
 WITH filtered AS(SELECT * FROM app.schedule_filtered(p_filter,CASE WHEN p_mine THEN actor ELSE null END)),paged AS(SELECT * FROM filtered ORDER BY day_index,time_start,id LIMIT size OFFSET(page-1)*size)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(app.schedule_dto(id) ORDER BY day_index,time_start,id) FROM paged),'[]'::jsonb),'total',(SELECT count(*) FROM filtered),'page',page,'pageSize',size) INTO result;RETURN result;END $$;
CREATE FUNCTION app.schedule_conflicts(p_session text,p_data jsonb,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c jsonb;BEGIN PERFORM app.master_guard(p_session,false);PERFORM app.schedule_dependencies();c:=app.schedule_candidate(p_data);RETURN jsonb_build_object('conflicts',app.schedule_collisions(c,p_id),'timeEnd',c->>'time_end','minutesPerJtm',(c->>'minutes_per_jtm')::int,'scheduledJtm',c->>'scheduled_jtm','authorizesMutation',false);END $$;
CREATE FUNCTION app.schedule_recaps(p_session text,p_filter jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result jsonb;BEGIN PERFORM app.master_guard(p_session,false);SELECT jsonb_build_object('rowCount',count(*),'totalScheduledJtm',coalesce(sum(scheduled_jtm),0)::numeric(16,4)::text,'basis','filtered_schedule_rows_not_attendance_or_honor') INTO result FROM app.schedule_filtered(p_filter,null);RETURN result;END $$;
CREATE FUNCTION app.schedule_today(p_session text,p_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;context jsonb;result jsonb;BEGIN
 actor:=auth_private.lifecycle_self(p_session);IF auth_private.resolve_actor(true) IS NULL THEN RAISE EXCEPTION 'ONBOARDING_REQUIRED' USING ERRCODE='42501';END IF;context:=app.day_context_internal(p_date);PERFORM app.schedule_dependencies();
 SELECT jsonb_build_object('items',CASE WHEN(context->>'kbmEnabled')::boolean THEN coalesce(jsonb_agg(app.schedule_dto(id) ORDER BY time_start,id),'[]'::jsonb) ELSE '[]'::jsonb END,'scheduledCount',count(*),'dayContext',context,'confirmationAvailable',false,'journalAvailable',false,'substitutionsAvailable',false) INTO result FROM app.teaching_schedules WHERE user_id=actor AND state<>'archived' AND p_date BETWEEN valid_from AND valid_to AND day_index=extract(dow FROM p_date)::int AND academic_period_id::text=context->>'academicPeriodId';RETURN result;END $$;
CREATE FUNCTION app.schedule_bulk_preview(p_session text,p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;item jsonb;items jsonb:='[]'::jsonb;v ops.schedule_previews%ROWTYPE;rev bigint;BEGIN
 actor:=app.master_guard(p_session,true);PERFORM app.schedule_dependencies();IF jsonb_typeof(p_request->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_request->'items') NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p_request->>'reason',''))) NOT BETWEEN 5 AND 500 OR(p_request-ARRAY['items','stopFrom','reason'])<>'{}'::jsonb OR(SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_request->'items') x)<>jsonb_array_length(p_request->'items') THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_request->'items') LOOP items:=items||jsonb_build_array(app.schedule_stop_internal((item->>'id')::uuid,(item->>'version')::bigint,(p_request->>'stopFrom')::date,false));END LOOP;
 SELECT revision INTO rev FROM app.calendar_state;INSERT INTO ops.schedule_previews(actor_id,request,state_revision) VALUES(actor,p_request,rev) RETURNING * INTO v;RETURN jsonb_build_object('previewId',v.id,'expiresAt',v.expires_at,'items',items,'count',jsonb_array_length(items));END $$;
CREATE FUNCTION app.schedule_bulk_commit(p_session text,p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE actor uuid;v ops.schedule_previews%ROWTYPE;item jsonb;rev bigint;BEGIN
 actor:=app.master_guard(p_session,true);PERFORM app.schedule_dependencies();SELECT * INTO v FROM ops.schedule_previews WHERE id=p_id FOR UPDATE;IF v.id IS NULL OR v.actor_id<>actor OR v.consumed_at IS NOT NULL OR v.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'CALENDAR_PREVIEW_INVALID' USING ERRCODE='42501';END IF;SELECT revision INTO rev FROM app.calendar_state;IF rev<>v.state_revision THEN RAISE EXCEPTION 'CALENDAR_PREVIEW_STALE' USING ERRCODE='40001';END IF;
 PERFORM set_config('app.master_reason',v.request->>'reason',true);FOR item IN SELECT value FROM jsonb_array_elements(v.request->'items') LOOP PERFORM app.schedule_stop_internal((item->>'id')::uuid,(item->>'version')::bigint,(v.request->>'stopFrom')::date,true);END LOOP;UPDATE ops.schedule_previews SET consumed_at=clock_timestamp() WHERE id=v.id;RETURN jsonb_build_object('committed',true,'count',jsonb_array_length(v.request->'items'));END $$;
CREATE FUNCTION app.schedule_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.state<>'archived' AND jsonb_array_length(app.schedule_collisions(to_jsonb(NEW),NEW.id))>0 THEN RAISE EXCEPTION 'SCHEDULE_COLLISION' USING ERRCODE='23505';END IF;
 IF extract(epoch FROM NEW.time_end)-extract(epoch FROM NEW.time_start)<>(NEW.scheduled_jtm*NEW.minutes_per_jtm+NEW.rest_minutes)*60 THEN RAISE EXCEPTION 'SCHEDULE_INVALID' USING ERRCODE='22023';END IF;RETURN NEW;END $$;
CREATE TRIGGER schedules_validate BEFORE INSERT OR UPDATE ON app.teaching_schedules FOR EACH ROW EXECUTE FUNCTION app.schedule_validate();
CREATE TRIGGER schedules_audit AFTER INSERT OR UPDATE ON app.teaching_schedules FOR EACH ROW EXECUTE FUNCTION app.master_audit('schedules');
CREATE TRIGGER schedules_context_revision AFTER INSERT OR UPDATE ON app.teaching_schedules FOR EACH STATEMENT EXECUTE FUNCTION app.calendar_revision_bump();
CREATE FUNCTION app.schedule_parent_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF TG_TABLE_NAME='academic_periods' THEN
 IF EXISTS(SELECT 1 FROM app.teaching_schedules WHERE academic_period_id=NEW.id AND state<>'archived' AND(NEW.archived_at IS NOT NULL OR valid_from<NEW.date_start OR valid_to>NEW.date_end)) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;
 ELSIF NEW.archived_at IS NOT NULL THEN
 IF TG_TABLE_NAME='classes' AND EXISTS(SELECT 1 FROM app.teaching_schedules WHERE class_id=NEW.id AND state<>'archived' AND valid_to>=(clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::date) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;
 IF TG_TABLE_NAME='subjects' AND EXISTS(SELECT 1 FROM app.teaching_schedules WHERE subject_id=NEW.id AND state<>'archived' AND valid_to>=(clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::date) THEN RAISE EXCEPTION 'MASTER_REFERENCED' USING ERRCODE='23503';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER schedules_period_guard BEFORE UPDATE ON app.academic_periods FOR EACH ROW EXECUTE FUNCTION app.schedule_parent_guard();
CREATE TRIGGER schedules_class_guard BEFORE UPDATE ON app.classes FOR EACH ROW EXECUTE FUNCTION app.schedule_parent_guard();
CREATE TRIGGER schedules_subject_guard BEFORE UPDATE ON app.subjects FOR EACH ROW EXECUTE FUNCTION app.schedule_parent_guard();
REVOKE ALL ON FUNCTION app.schedule_validate(),app.schedule_dependencies(),app.schedule_weekday_exists(date,date,int),app.schedule_dto(uuid),app.schedule_candidate(jsonb),app.schedule_collisions(jsonb,uuid),app.schedule_save(text,uuid,bigint,jsonb,text),app.schedule_stop_internal(uuid,bigint,date,boolean),app.schedule_stop(text,uuid,bigint,date,text),app.schedule_filtered(jsonb,uuid),app.schedule_list(text,jsonb,boolean),app.schedule_conflicts(text,jsonb,uuid),app.schedule_recaps(text,jsonb),app.schedule_today(text,date),app.schedule_bulk_preview(text,jsonb),app.schedule_bulk_commit(text,uuid),app.schedule_parent_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.schedule_save(text,uuid,bigint,jsonb,text),app.schedule_stop(text,uuid,bigint,date,text),app.schedule_list(text,jsonb,boolean),app.schedule_conflicts(text,jsonb,uuid),app.schedule_recaps(text,jsonb),app.schedule_today(text,date),app.schedule_bulk_preview(text,jsonb),app.schedule_bulk_commit(text,uuid) TO sim_guru_business;
CREATE OR REPLACE FUNCTION app.calendar_preview(p_session text,p_kind text,p_request jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE a uuid;days jsonb;v ops.calendar_previews%ROWTYPE;rev bigint;BEGIN
 a:=app.master_guard(p_session,true);days:=app.calendar_changes(p_kind,p_request,false);SELECT revision INTO rev FROM app.calendar_state WHERE singleton;
 INSERT INTO ops.calendar_previews(actor_id,kind,request,state_revision) VALUES(a,p_kind,p_request,rev) RETURNING * INTO v;
 RETURN jsonb_build_object('previewId',v.id,'expiresAt',v.expires_at,'kind',p_kind,'action',p_request->>'action','count',jsonb_array_length(days),'days',days,'assignmentIntegration','teaching_ready','policyVersion','calendar-v1');END $$;

RESET ROLE;
